parameters.jsCode:
// 🔹 SAFE INPUT
const input = $json || {};

// 🔹 SAFE BODY
const body = input.body && typeof input.body === "object"
  ? input.body
  : {};

// 🔹 SAFE RAW REQUEST PARSE
let parsed = {};

try {
  if (typeof body.rawRequest === "string") {
    parsed = JSON.parse(body.rawRequest);
  } else if (typeof body.rawRequest === "object") {
    parsed = body.rawRequest;
  }
} catch (e) {
  parsed = {};
}

// 🔹 Extract email safely (Adjust 'q5_email' if Jotform field ID changes)
const rawEmail = (parsed?.q5_email || "").toString().toLowerCase().trim();

// 🔹 Extract domain from email for Hunter.io verification
const emailDomain = rawEmail.includes("@")
  ? rawEmail.split("@")[1]
  : "";

// 🔹 Default Metadata / Fallbacks (Since frontend fields are removed)
const leadSource = parsed?.q40_leadSource || "Single Field Form";

// 🔹 PH Timestamp
const phTimestamp = new Date().toLocaleString("en-US", {
  timeZone: "Asia/Manila",
  year: "numeric",
  month: "long",
  day: "numeric",
  hour: "2-digit",
  minute: "2-digit",
  hour12: false
}) + " PHT";

// 🔥 FINAL SAFE OUTPUT FOR HUNTER.IO ENRICHMENT
return {
  json: {
    email: rawEmail,
    domain: emailDomain,
    lead_source: leadSource,
    // We pass empty strings so your CRM automation can easily map and 
    // overwrite them when Hunter.io returns the real data:
    first_name: "",
    last_name: "",
    name: "Unknown",
    company: "Unknown",
    submitted_at: new Date().toISOString(),
    processed_at: phTimestamp
  }
};

// 🔹 SAFE INPUT (prevents crash)
const data = $json && typeof $json === "object" ? $json : {};

// 🔹 SAFE EXTRACTION (from previous Jotform node)
const lead = data.lead || data;

// 🧼 CLEANING & NORMALIZING
const email = (lead.email || "").toString().toLowerCase().trim();
const domain = (lead.domain || "").toString().toLowerCase().trim();
const lead_source = lead.lead_source || "Single Field Form";
const submitted_at = lead.submitted_at || null;
const processed_at = lead.processed_at || null;

// 👤 INITIALIZE EMPTY IDENTITY FIELDS FOR HUNTER.IO TO FILL NEXT
// We leave these blank/Unknown because the user didn't type them in the form.
const rawName = "Unknown";
const first_name = "";
const last_name = "";
const company = "Unknown";

return {
  json: {
    lead: {
      email,
      domain,
      name: rawName, 
      first_name,
      last_name,
      company,
      lead_source,
      submitted_at,
      processed_at
    }
  }
};

// 🔹 GET NORMALIZED LEAD FROM PREVIOUS NODE
const lead = $json.lead || {};

// ==============================
// 🔍 CONFIGURATION LISTS
// ==============================
const junkWords = ["test", "fake", "asdf", "none", "spam", "qwerty"];

const personalDomains = [
  "gmail.com",
  "yahoo.com",
  "outlook.com",
  "hotmail.com",
  "icloud.com",
  "msn.com",
  "proton.me",
  "protonmail.com"
];

// ==============================
// 🔹 VALIDATION CHECKS
// ==============================
// 1. Check if it's a valid email structure
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const isValidFormat = emailRegex.test(lead.email || "");

// 2. Identify personal email providers
const isPersonalEmail = personalDomains.includes(lead.domain || "");

// 3. Scan the email string for obvious garbage/spam words
const isJunkLead = junkWords.some((word) => {
  return (lead.email || "").includes(word);
});

// ==============================
// 🔹 FINAL DECISION
// ==============================
// The lead passes if formatting is correct, it has no spam keywords, 
// and it is NOT a personal email domain.
const shouldProcess = isValidFormat && !isJunkLead && !isPersonalEmail;

// ==============================
// 🔥 OUTPUT
// ==============================
return {
  json: {
    // Forward the original data untouched
    lead, 
    // Forward the updated status flags
    flags: {
      isEmailValid: isValidFormat,
      isPersonalEmail,
      isJunkLead,
      shouldProcess,
    },
  },
};

const input = $json;

// SAFETY CHECK (prevents crash)
if (!input || typeof input !== "object") {
  return [
    {
      json: {
        error: "Invalid input received",
        raw: input,
      },
    },
  ];
}

// SAFE EXTRACTION (Aligns with previous Normalize/Validate nodes)
const lead = input.lead || {};
const initialFlags = input.flags || {};

// ZEROBOUNCE AND HUNTER DATA EXTRACTION
// Note: Adjust the fallback strings/objects if your preceding nodes structured them differently
const validation = {
  status: input.status || "unknown", // From ZeroBounce (valid, invalid, catch-all)
  free_email: initialFlags.isPersonalEmail || input.free_email || false, // From validation node or Hunter
  domain_age_days: input.domain_age_days || 0,
  mx_found: input.mx_found !== undefined ? input.mx_found : false, 
};

const enrichment = input.data || {};
const person = enrichment.person || {};
const company = enrichment.company || {};

// INITIALIZE SCORE
let score = 0;

// ==============================
// 🎯 1. EMAIL VALIDATION SCORING
// ==============================
if (validation.status === "valid") {
  score += 25;
} else if (validation.status === "catch-all") {
  score += 15;
}

// ⚠️ BUG FIX: n8n boolean fields are true/false, not the string "true"
if (validation.mx_found === true || validation.mx_found === "true") {
  score += 3;
}

const domainAge = Number(validation.domain_age_days);
if (domainAge > 3650) score += 5;
else if (domainAge > 1000) score += 3;

// ⚠️ BUG FIX: Ensures accurate boolean check
if (validation.free_email === true || validation.free_email === "true") {
  score -= 8;
}

// ==============================
// 🏢 2. COMPANY SIZE SCORING
// ==============================
const employees = company?.metrics?.employees || company?.size;

if (employees === "11-50") score += 15;
else if (employees === "51-200") score += 22;
else if (employees === "201-1000") score += 26;
else if (employees === "1000+") score += 30;
else score += 8; // Default bucket for missing/small company sizes

// ==============================
// 👔 3. SENIORITY SCORING
// ==============================
const seniority = (person?.employment?.seniority || "").toLowerCase();

if (seniority === "executive" || seniority === "c-level") score += 25;
else if (seniority === "manager" || seniority === "director") score += 18;
else score += 6;

// ==============================
// 📣 4. SOURCE SCORING
// ==============================
const source = (lead.lead_source || "").toLowerCase();

if (source.includes("referral")) score += 20;
else if (source.includes("website")) score += 17;
else if (source.includes("organic")) score += 15;
else if (source.includes("paid")) score += 10;
else if (source.includes("cold")) score += 5;

// ==============================
// 📊 FINAL RANGE BOUNDS (0 - 100)
// ==============================
const finalScore = Math.max(0, Math.min(100, Math.round(score)));

let priority = "low";
if (finalScore >= 70) priority = "high";
else if (finalScore >= 40) priority = "medium";

// 🔥 CRITICAL: ALWAYS RETURN THIS FORMAT
return [
  {
    json: {
      lead,
      validation,
      enrichment,
      score: finalScore,
      priority,
    },
  },
];
